#include <bits/stdc++.h>
using namespace std;
const long long MOD=998244353;
int main() {
	// your code goes hereint usingint t;
	int t;
	cin>>t;
	while(t--){
	    int n;
	    cin>>n;
	    vector<int> a(n+1);
	    vector<vector<int>> byVal(n+1);
	    for(int i=1;i<=n;i++){
	        cin>>a[i];
	        byVal[a[i]].push_back(i);
	    }
	    vector<int> J(n+1),X(n+1),J2(n+1),Y(n+1);
	
	    
	    for(int i=1;i<=n;i++){
	        J[i]=(i+1)/2;
	        
	        X[i]=n-i/2;
	        int c=(n-i+2)/2;
	        J2[i]=n+1-c;
	        Y[i]=i-1+c;
	    }
	    
	    
	    auto conditionH=[&](int i,int l,int r,int pos){
	        int v=a[i];
	        auto check=[&](int target,int cap){
	            if(v<cap)return pos==target;
	            if(v==cap)return l+1<=target&&target<=n-r;
	            return false;
	        };return check(J[i],X[i])||check(J2[i],Y[i]);
	    };
	    vector<long long >dp(n+1,0),ndp(n+1,0);
	    dp[0]=1;
	    for(int v=1;v<=n;v++){
	        int placed=v-1;
	        fill(ndp.begin(),ndp.end(),0);
	        for(int l=0;l<=placed;l++){
	            if(!dp[l]) continue;
	            
	            int r=placed-l;
	            auto tryP=[&](int pos,int nl){
	                for(int i:byVal[v]){
	                    if(!conditionH(i,l,r,pos)) return;
	                }ndp[nl]=(ndp[nl]+dp[l])%MOD;
	            };
	            if(v==n) tryP(l+1,l);
	            else{
	                tryP(l+1,l+1);
	                tryP(n-r,l);
	            }
	        }
	        swap(dp,ndp);
	    }long long ans=0;
	    for(long long x:dp)ans=(ans+x)%MOD;
	    
	    cout<<ans<<endl;
	}

}
